<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';require_once __DIR__ . '/../includes/wardrobe.php';$user=require_role('donor');$pdo=db();
if(is_post()){verify_csrf();$pledge=(int)($_POST['pledge_id']??0);$pdo->beginTransaction();try{$stmt=$pdo->prepare("SELECT id FROM donation_pledges WHERE id=? AND donor_id=? AND status='pending' FOR UPDATE");$stmt->execute([$pledge,$user['id']]);if(!$stmt->fetch())throw new RuntimeException('Only pending pledges can be cancelled.');$pdo->prepare("UPDATE donation_pledges SET status='cancelled',updated_at=NOW() WHERE id=?")->execute([$pledge]);update_wardrobe_reservations($pdo,$pledge,'released');$pdo->commit();flash('success','Your pending pledge was cancelled.');}catch(Throwable $error){$pdo->rollBack();flash('error',$error instanceof RuntimeException?$error->getMessage():'We could not cancel that pledge.');}redirect('donor/pledges.php');}
$stmt=$pdo->prepare("SELECT dp.*,cr.title,c.organization_name,COALESCE(SUM(di.quantity),0) quantity FROM donation_pledges dp JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id LEFT JOIN donation_items di ON di.pledge_id=dp.id WHERE dp.donor_id=? GROUP BY dp.id ORDER BY dp.created_at DESC");$stmt->execute([$user['id']]);$pledges=$stmt->fetchAll();$pageTitle='Your pledges';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">Your giving history</span><h1>Every promise, in one place.</h1></div><a class="button button-outline" href="<?=e(url('donor/dashboard.php'))?>">Back to dashboard</a></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Charity request</th><th>Items</th><th>Created</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($pledges as $p):?><tr><td><strong><?=e($p['title'])?></strong><br><span class="muted"><?=e($p['organization_name'])?></span></td><td><?=$p['quantity']?></td><td><?=format_date($p['created_at'])?></td><td><span class="status <?=e(status_class($p['status']))?>"><?=e($p['status'])?></span></td><td class="row-actions"><?php if($p['status']==='approved'):?><a class="button button-small" href="<?=e(url('donor/appointment.php?pledge='.$p['id']))?>">Book</a><?php endif;?><?php if($p['status']==='pending'):?><form method="post" data-loading data-confirm="Cancel this pending pledge?"><?=csrf_field()?><input type="hidden" name="pledge_id" value="<?=$p['id']?>"><button class="button button-danger button-small">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
